mapper.select:
SELECT COUNT(*)
FROM pattern_executions pe
JOIN financial_patterns fp
  ON fp.financial_pattern_id = pe.financial_pattern_id
WHERE fp.user_id = #{userId}
  AND pe.pattern_execution_id = #{patternExecutionId}
  AND pe.source_bank_account_id = #{sourceAccountId}
  AND pe.status = 'STARTED'

mapper.update:
UPDATE pattern_executions pe
JOIN financial_patterns fp
  ON fp.financial_pattern_id = pe.financial_pattern_id
SET pe.source_bank_account_id = #{sourceAccountId}
WHERE fp.user_id = #{userId}
  AND pe.pattern_execution_id = #{patternExecutionId}
  AND pe.status = 'STARTED'
  AND pe.source_bank_account_id IS NULL

mapper.select:
SELECT COUNT(*)
FROM transactions
WHERE user_id = #{userId}
  AND transaction_type = 'TRANSFER_OUT'
  AND transaction_at >= #{from}
  AND transaction_at <= #{to}

mapper.update:
UPDATE bank_accounts
SET balance = balance - #{amount}
WHERE user_id = #{userId}
  AND bank_account_id = #{accountId}
  AND registered_person_id IS NULL
  AND balance >= #{amount}

UPDATE anomaly_events
SET rechecked = #{rechecked},
    final_action = 'CANCEL',
    resolved_at = #{resolvedAt}
WHERE user_id = #{userId}
  AND anomaly_event_id = #{anomalyEventId}
  AND final_action IS NULL

UPDATE anomaly_events
SET transaction_id = #{transactionId},
    rechecked = #{rechecked},
    final_action = 'CONTINUE',
    resolved_at = #{resolvedAt}
WHERE user_id = #{userId}
  AND anomaly_event_id = #{anomalyEventId}
  AND final_action IS NULL

UPDATE pattern_executions
SET status = #{status},
    ended_at = #{endedAt}
WHERE pattern_execution_id = #{patternExecutionId}
  AND status = 'STARTED'
